#!/usr/bin/perl
use strict; use warnings;
# usage: perl iter.pl reps.txt   (reps.txt: old,new per line; '#' comments)
my $repsfile = $ARGV[0];
open my $fh, '<', $repsfile or die;
my @reps;
while (my $l = <$fh>) { chomp $l; next if $l =~ /^#/ || $l =~ /^\s*$/; my ($o,$n) = split /,/, $l, 2; push @reps, [$o,$n]; }
close $fh;
# load synonym families
open my $sf, '<', 'synonyms.txt' or die;
my %fam;  # word -> family index
my @fams;
my $fi = 0;
while (my $l = <$sf>) { chomp $l; next unless $l =~ /\S/; my @w = split /,\s*/, $l; for my $x (@w) { $fam{$x} = $fi; } push @fams, \@w; $fi++; }
close $sf;
# validate replacements
for my $r (@reps) {
    my ($o,$n) = @$r;
    die "OLD word '$o' not in any synonym family\n" unless exists $fam{$o};
    die "NEW word '$n' not in same family as '$o' (fam: @{$fams[$fam{$o}]})\n" unless exists $fam{$n} && $fam{$n} == $fam{$o};
}
# apply to original text
open my $ih, '<', 'input.orig.tex' or die;
local $/; my $text = <$ih>; close $ih;
for my $r (@reps) {
    my ($o,$n) = @$r;
    my $pat = qr/(?<![A-Za-z])\Q$o\E(?![A-Za-z])/;
    my $count = ($text =~ s/$pat/$n/g);
    print "REPLACE $o -> $n : $count occurrence(s)\n";
}
open my $oh, '>', 'input.tex' or die; print $oh $text; close $oh;
# compile
system('pdflatex','-interaction=nonstopmode','main.tex') > '/dev/null';
my $log = do { local $/; open my $L, '<', 'main.log'; <$L> };
my @of = $log =~ /(Overfull \\hbox \([\d.]+pt too wide\) in paragraph at lines [\d-]+)\n((?:\\OT1\/cmr\/m\/n\/10 .*?)\n)/g;
if (!@of) { print "NO OVERFULLS\n"; }
else {
    print "OVERFULL COUNT: ", scalar(@of/2), "\n";
    for (my $i=0; $i<@of; $i+=2) { print "$of[$i]\n    $of[", $i+1, "]\n"; }
}
EOF
echo done

