#!/usr/bin/perl
use strict; use warnings;
# word-level alignment check: every changed word must be a same-family synonym
open my $a, '<', 'work/input.orig.tex' or die; local $/; my $orig = <$a>; close $a;
open my $b, '<', 'input.tex' or die; my $new = <$b>; close $b;
open my $s, '<', 'synonyms.txt' or die; my %fam; my $fi=0;
while (my $l=<$s>) { chomp $l; next unless $l=~/\S/; for my $w (split /,\s*/,$l){$fam{$w}=$fi;} $fi++; }
close $s;
my @wo = split /\s+/, $orig;
my @wn = split /\s+/, $new;
my $i=0; $i=@wo while $i<@wo && $i<@wn && $wo[$i] eq $wn[$i];  # common prefix
my $changes=0;
while ($i < @wo && $i < @wn) {
    if ($wo[$i] eq $wn[$i]) { $i++; next; }
    # find resync: try shifting
    my $found=0;
    for my $k (1..5) {
        last if $i+$k >= @wo || $i+$k >= @wn;
        next unless $wo[$i+$k] eq $wn[$i+$k];
        my @old_w = @wo[$i..$i+$k-1]; my @new_w = @wn[$i..$i+$k-1];
        die "UNALIGNED CHANGE: old=[@old_w] new=[@new_w]\n" unless @old_w==@new_w;
        for (my $j=0; $j<@old_w; $j++) {
            my ($o,$n) = ($old_w[$j], $new_w[$j]);
            (my $ob=$o) =~ s/[^A-Za-z]//g; (my $nb=$n) =~ s/[^A-Za-z]//g;
            $changes++;
            if (!exists $fam{$ob} || !exists $fam{$nb} || $fam{$ob} ne $fam{$nb}) {
                die "ILLEGAL: '$o' -> '$n' (bases '$ob'/'$nb') not same family\n";
            }
            print "OK: $o -> $n (family #$fam{$ob})\n";
        }
        $i += $k; $found=1; last;
    }
    die "CANNOT ALIGN at i=$i: old='@wo[$i]' new='@wn[$i]'\n" unless $found;
}
die "suffix mismatch\n" if $i<@wo || $i<@wn;
print "TOTAL CHANGES: $changes\n";
print "ALL CHANGES ARE PERMITTED SYNONYMS\n" if $changes>0;
EOF
