    $suf++ while $suf < length($A)-$p && $suf < length($B)-$p
                && substr($A,length($A)-1-$suf,1) eq substr($B,length($B)-1-$suf,1);
    my $o = substr($A, $p, length($A)-$p-$suf);
    my $n = substr($B, $p, length($B)-$p-$suf);
    die "non-word change at token $i: '$A' -> '$B' (mids '$o'/'$n')\n"
        unless $o =~ /^[A-Za-z]+$/ && $n =~ /^[A-Za-z]+$/;
    die "not a family word: '$o' or '$n'\n"
        unless exists $fam{$o} && exists $fam{$n};
    die "different families: '$o' (#$fam{$o}) vs '$n' (#$fam{$n})\n"
        unless $fam{$o} eq $fam{$n};
    $changes++;
    print "OK token $i: [$A] -> [$B]   word: $o -> $n (family #$fam{$o})\n";
}
